def neigh_count(g,r,c):
    n=0
    for dr in (-1,0,1):
        for dc in (-1,0,1):
            if dr==0 and dc==0: continue
            rr,cc=r+dr,c+dc
            if 0<=rr<13 and 0<=cc<14 and g[rr,cc]==0: n+=1
    return n
